 boolean factoryConfiguration(){try{PhaseEngine defaults=new PhaseEngine();if(UsagiPreset.APP.equals(pkg))UsagiPreset.install(defaults,usagiReferences());else if(FarmPreset.APP.equals(pkg))FarmPreset.install(defaults,references("farm-preset.json"));else if(CoinPreset.APP.equals(pkg))CoinPreset.install(defaults,references("coin-preset.json"));else if(ShoppingPreset.APP.equals(pkg))ShoppingPreset.install(defaults,references("shopping-preset.json"));else if(BoxPreset.APP.equals(pkg))BoxPreset.install(defaults,references("box-preset.json"));else if(PoipoiPreset.APP.equals(pkg))PoipoiPreset.install(defaults,references("poipoi-preset.json"));else return false;if(AutomatonGraph.sameConfiguration(engine,defaults))return true;if(PoipoiPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,PoipoiPreset.version191Defaults(references("poipoi-preset.json"))))return true;if(ShoppingPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,ShoppingPreset.version182Defaults(references("shopping-preset.json"))))return true;if(CoinPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,CoinPreset.version179Defaults(references("coin-preset.json"))))return true;if(CoinPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,CoinPreset.version178Defaults(references("coin-preset.json"))))return true;if(CoinPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,CoinPreset.version170Defaults(references("coin-preset.json"))))return true;if(CoinPreset.APP.equals(pkg)&&AutomatonGraph.sameConfiguration(engine,CoinPreset.previousDefaults(references("coin-preset.json"))))return true;if(UsagiPreset.APP.equals(pkg)){java.util.Map<String,float[]> legacy=usagiReferences();legacy.remove("promo");legacy.remove("promo-close");PhaseEngine previous=new PhaseEngine();UsagiPreset.install(previous,legacy);return AutomatonGraph.sameConfiguration(engine,previous);}return false;}catch(Exception invalid){return false;}}

